import React, { useState, useEffect, useRef, useCallback } from 'react';
import './SearchContainer.css';

const SearchContainer = ({ onLocationSelect }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [showResults, setShowResults] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isWaiting, setIsWaiting] = useState(false); // New state for waiting indicator
  const [selectedIndex, setSelectedIndex] = useState(-1);
  const [instantSuggestions, setInstantSuggestions] = useState([]);
  const searchTimeout = useRef(null);
  const searchInputRef = useRef(null);
  const searchCache = useRef(new Map());

  // No hardcoded places - rely entirely on API for accurate results

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (searchInputRef.current && !searchInputRef.current.contains(event.target)) {
        setShowResults(false);
        setSelectedIndex(-1);
      }
    };

    document.addEventListener('click', handleClickOutside);
    return () => document.removeEventListener('click', handleClickOutside);
  }, []);

  // Generate instant suggestions based on input (minimal local suggestions)
  // No instant suggestions - rely entirely on API for precise results
  const generateInstantSuggestions = useCallback((query) => {
    return []; // No hardcoded suggestions - API will provide all results
  }, []);

  const handleSearchInput = (e) => {
    const query = e.target.value; // Don't trim immediately to allow spaces
    setSearchQuery(query);
    setSelectedIndex(-1);
    
    const trimmedQuery = query.trim();
    
    if (trimmedQuery.length < 1) {
      setShowResults(false);
      setSearchResults([]);
      setInstantSuggestions([]);
      return;
    }

    // Always show results for any non-empty query
    setShowResults(true);

    // Clear previous timeout
    if (searchTimeout.current) {
      clearTimeout(searchTimeout.current);
    }

    // Only search when user stops typing - wait for pause in typing
    if (trimmedQuery.length >= 1) {
      setIsWaiting(true); // Show waiting indicator
      setIsLoading(false); // Not loading yet, just waiting
      
      // Wait for user to stop typing before searching
      searchTimeout.current = setTimeout(() => {
        setIsWaiting(false); // Hide waiting indicator
        setIsLoading(true); // Start loading
        searchLocations(trimmedQuery);
      }, 800); // Increased to 800ms to wait for user to stop typing
    }
  };

  const searchLocations = async (query) => {
    // Check cache first
    const cacheKey = query.toLowerCase().trim();
    if (searchCache.current.has(cacheKey)) {
      const cached = searchCache.current.get(cacheKey);
      if (Date.now() - cached.timestamp < 300000) { // 5 minute cache
        setSearchResults(cached.results);
        setIsLoading(false);
        return;
      }
    }

    try {
      // Use AbortController for faster cancellation
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 10000); // 10 second timeout for enhanced search
      
      // Enhanced search query with comprehensive parameters
      const searchParams = new URLSearchParams({
        q: query
      });
      
      const response = await fetch(`/api/search?${searchParams.toString()}`, {
        signal: controller.signal,
        headers: {
          'Accept': 'application/json',
          'Content-Type': 'application/json'
        }
      });
      
      clearTimeout(timeoutId);
      
      if (!response.ok) {
        throw new Error(`Search failed: ${response.status}`);
      }
      
      const data = await response.json();
      
      if (data.success && data.results && data.results.length > 0) {
        // Cache the results
        searchCache.current.set(cacheKey, {
          results: data.results,
          timestamp: Date.now()
        });
        
        // Limit cache size
        if (searchCache.current.size > 100) {
          const entries = Array.from(searchCache.current.entries());
          entries.sort((a, b) => b[1].timestamp - a[1].timestamp);
          searchCache.current = new Map(entries.slice(0, 50));
        }
        
        setSearchResults(data.results);
      } else {
        setSearchResults([]);
      }
    } catch (error) {
      if (error.name === 'AbortError') {
        console.log('Search request was cancelled');
      } else {
        console.error('Search error:', error);
      }
      setSearchResults([]);
    } finally {
      setIsLoading(false);
      setIsWaiting(false); // Clear waiting state when search completes
    }
  };

  const handleLocationSelect = (result) => {
    const location = {
      name: result.displayName,
      lat: result.latitude,
      lon: result.longitude
    };
    
    setSearchQuery(result.displayName);
    setShowResults(false);
    setSelectedIndex(-1);
    onLocationSelect(location);
  };

  const handleKeyDown = (e) => {
    const totalResults = instantSuggestions.length + searchResults.length;
    
    switch (e.key) {
      case 'ArrowDown':
        if (!showResults) return;
        e.preventDefault();
        setSelectedIndex(prev => 
          prev < totalResults - 1 ? prev + 1 : 0
        );
        break;
      case 'ArrowUp':
        if (!showResults) return;
        e.preventDefault();
        setSelectedIndex(prev => 
          prev > 0 ? prev - 1 : totalResults - 1
        );
        break;
      case 'Enter':
        e.preventDefault();
        if (showResults && selectedIndex >= 0 && selectedIndex < totalResults) {
          const allResults = [...instantSuggestions, ...searchResults];
          handleLocationSelect(allResults[selectedIndex]);
        } else if (searchQuery.trim().length >= 1) {
          // Trigger search immediately on Enter for any non-empty query
          const trimmedQuery = searchQuery.trim();
          setIsWaiting(false); // Clear waiting state
          setIsLoading(true);
          setShowResults(true);
          // Clear any pending timeout and search immediately
          if (searchTimeout.current) {
            clearTimeout(searchTimeout.current);
          }
          searchLocations(trimmedQuery);
        }
        break;
      case 'Escape':
        setShowResults(false);
        setSelectedIndex(-1);
        break;
    }
  };

  const highlightText = (text, query) => {
    if (!query) return text;
    
    const regex = new RegExp(`(${query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi');
    const parts = text.split(regex);
    
    return parts.map((part, index) => 
      regex.test(part) ? (
        <span key={index} className="highlighted-text">{part}</span>
      ) : part
    );
  };

  // Process results to prioritize searched name when there's a good match
  const processResults = (results) => {
    return results.map(result => {
      const displayName = result.displayName;
      const searchedName = searchQuery.trim().toLowerCase();
      
      // Special handling for specific place names
      const specificPlaces = {
        'fairy meadows': 'Fairy Meadows',
        'nanga parbat': 'Nanga Parbat',
        'hunza': 'Hunza Valley',
        'skardu': 'Skardu',
        'gilgit': 'Gilgit',
        'chitral': 'Chitral',
        'swat': 'Swat Valley',
        'murree': 'Murree',
        'nathia gali': 'Nathia Gali',
        'kaghan': 'Kaghan Valley',
        'naran': 'Naran',
        'shogran': 'Shogran',
        'siri paye': 'Siri Paye',
        'lalazar': 'Lalazar',
        'saif ul malook': 'Saif ul Malook',
        'kumrat': 'Kumrat Valley',
        'kalash': 'Kalash Valley',
        'deosai': 'Deosai Plains',
        'shangrila': 'Shangrila',
        'attabad': 'Attabad Lake',
        'rush lake': 'Rush Lake',
        'baltoro': 'Baltoro Glacier',
        'concordia': 'Concordia',
        'k2': 'K2',
        'gasherbrum': 'Gasherbrum',
        'broad peak': 'Broad Peak',
        'masherbrum': 'Masherbrum',
        'trango': 'Trango Towers',
        'baltit': 'Baltit Fort',
        'altit': 'Altit Fort',
        'khunjerab': 'Khunjerab Pass',
        'muztagh': 'Muztagh',
        'shimshal': 'Shimshal Valley',
        'gojal': 'Gojal Valley',
        'phander': 'Phander Lake',
        'rush phari': 'Rush Phari',
        'batura': 'Batura Glacier',
        'hispar': 'Hispar Glacier',
        'biafo': 'Biafo Glacier',
        'snow lake': 'Snow Lake'
      };
      
      // Check for exact match in specific places
      if (specificPlaces[searchedName]) {
        const parts = displayName.split(',');
        const location = parts[0].trim();
        const region = parts[1] ? parts[1].trim() : '';
        const country = parts[2] ? parts[2].trim() : '';
        
        // Use the specific place name as the primary name
        let newDisplayName = specificPlaces[searchedName];
        if (region && region !== specificPlaces[searchedName]) {
          newDisplayName += `, ${region}`;
        }
        if (country) {
          newDisplayName += `, ${country}`;
        }
        
        return {
          ...result,
          displayName: newDisplayName
        };
      }
      
      // General case: Check if the searched name is contained in the display name
      if (displayName.toLowerCase().includes(searchedName)) {
        // Extract the part that matches the search and use it as the primary name
        const parts = displayName.split(',');
        const firstPart = parts[0].trim();
        
        // If the first part contains the searched name, use it as is
        if (firstPart.toLowerCase().includes(searchedName)) {
          return {
            ...result,
            displayName: firstPart + (parts.length > 1 ? ', ' + parts.slice(1).join(', ') : '')
          };
        }
        
        // Otherwise, try to find the best match within the display name
        const words = displayName.split(' ');
        const matchingWords = words.filter(word => 
          word.toLowerCase().includes(searchedName) || 
          searchedName.includes(word.toLowerCase())
        );
        
        if (matchingWords.length > 0) {
          const bestMatch = matchingWords[0];
          const remainingParts = parts.filter(part => 
            !part.toLowerCase().includes(bestMatch.toLowerCase())
          );
          
          return {
            ...result,
            displayName: bestMatch + (remainingParts.length > 0 ? ', ' + remainingParts.join(', ') : '')
          };
        }
      }
      
      return result;
    });
  };

  const allResults = [...instantSuggestions, ...processResults(searchResults)];

  return (
    <div className="search-container-new">
      <div className="search-input-wrapper-new" ref={searchInputRef}>
        <div className="search-input-container-new">
          <input
            type="text"
            className="search-input-new"
            placeholder="Enter location name (e.g., Karachi, Lahore)..."
            value={searchQuery}
            onChange={handleSearchInput}
            onKeyDown={handleKeyDown}
            onFocus={() => {
              if (searchQuery.trim().length >= 1) {
                setShowResults(true);
              }
            }}
          />
          <i className="fas fa-search search-icon-new"></i>
        </div>
        
        {showResults && (
          <div className="search-results-new">
            {isWaiting ? (
              <div className="search-result-item-new">
                <i className="fas fa-clock"></i> Waiting for you to finish typing...
              </div>
            ) : isLoading && searchResults.length === 0 ? (
              <div className="search-result-item-new">
                <i className="fas fa-spinner fa-spin"></i> Searching...
              </div>
            ) : allResults.length === 0 ? (
              <div className="search-result-item-new">No locations found</div>
            ) : (
              allResults.map((result, index) => {
                const isPakistan = result.country && result.country.toLowerCase() === 'pakistan';
                const countryBadge = isPakistan ? 
                  <span className="result-country-new pakistan">Pakistan</span> : 
                  <span className="result-country-new">{result.country || 'Unknown'}</span>;
                
                const isSelected = index === selectedIndex;
                const isInstant = result.isInstant;
                
                return (
                  <div 
                    key={index}
                    className={`search-result-item-new ${isSelected ? 'selected' : ''} ${isInstant ? 'instant' : ''}`}
                    onClick={() => handleLocationSelect(result)}
                    onMouseEnter={() => setSelectedIndex(index)}
                  >
                    <div className="result-name-new">
                      {highlightText(result.displayName, searchQuery)}
                      {countryBadge}
                      {isInstant && <span className="instant-badge-new">Quick</span>}
                    </div>
                    <div className="result-details-new">
                      {result.latitude.toFixed(6)}°N, {result.longitude.toFixed(6)}°E
                      {result.state && result.state !== result.country && (
                        <span style={{ marginLeft: '10px', color: 'rgba(255, 255, 255, 0.6)' }}>
                          • {result.state}
                        </span>
                      )}
                    </div>
                  </div>
                );
              })
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default SearchContainer;
